import type { Beat } from './quest-beats';
// Opening scene per main storyline. Each one sets up only the story's starting hook (시작 계기) in its own city,
// and never mentions what later acts reveal (e.g. the coffin inside the sunken vault ship).
// The first quest and opening choices are drawn from this text, so it must match the game's chosen main story.

// startPlaces: map pin names to start at, best first (older saved maps may lack the first one).
// firstQuest: a fixed, easy errand (go somewhere, sign up, report) that opens the story without asking the player to uncover anything yet.
// questChain: the main quests that follow firstQuest, in order; finishing the last one is the ending.
// act marks the step whose completion closes that act of the main story (4 = the finale).
// beats: how the step gets done, in order (quest-beats.ts): talks, fights, places and choices the game itself checks,
// each with what it brings, so the story moves on a fixed track and the mastermind comes out only when a beat says so.
// firstBeats are the opening errand's (firstQuest).
export type MainStep = { q: string; act?: 1 | 2 | 3 | 4; beats: Beat[] };
// startItems: what the prologue puts in the hero's hands (the knight's sword), given once at the start of the story.
export type StoryItem = { name: string; kind: 'weapon' | 'armor' | 'accessory' | 'item'; grade: 0 | 1 | 2 | 3 | 4 | 5; desc: string };
export type MainPrologue = { title: string; city: string; startPlaces: string[]; firstQuest: string; firstBeats: Beat[]; startItems?: StoryItem[]; questChain?: MainStep[]; text: string; actions: [string, string, string, string] };

