    text: `잿빛 성벽 너머로 그림우드의 검은 숲이 끝없이 펼쳐진 변경 성채 도시 레븐홀트. 북문 초소 위에는 마물로부터 국경을 지키는 변경 기사단의 깃발이 펄럭이고, 개척민의 수레와 모험가의 말발굽이 진흙 길을 메운다.

레븐홀트로 오는 마지막 고갯길에서 당신은 마물에게 당해 쓰러진 늙은 기사를 만났다. 그는 숨을 거두기 전 잿빛 갈매기 문장이 새겨진 낡은 인장 반지를 당신 손에 쥐여 주며 "이 문장에 씌운 누명을…"이라는 말만 남겼다. 성문 경비병의 말로는 스무 해 전 반역죄로 작위와 영지를 모두 잃은 기사 가문의 마지막 사람이었다고 한다.

오늘 북문 초소 게시판에 변경 기사단의 신입 단원 모병 공고가 붙었다. "출신을 묻지 않음. 실력에 자신 있는 자." 공고 앞에는 벌써 농가의 딸들과 떠돌이 용병들이 줄을 섰고, 초소 위에서는 은빛 머리의 기사단장이 그들을 말없이 내려다보고 있다.`,
