    text: `푸른 바다가 햇빛을 반사하는 사레타 항구. 거대한 범선들이 선창을 메우고, 뱃사람과 상인, 모험가들이 좁은 부두를 오간다. 먼 곳에서 온 이들이 이름 하나 얻으려고 모여드는 항구다.

용과 싸운 기사, 마물 떼를 막은 용병단, 이름 하나로 대륙을 울린 모험가들. 그 이야기들이 시작된 곳도 대개 이런 부두였다. 오늘 당신은 긴 뱃길 끝에 짐을 짊어지고 7번 부두에 발을 디뎠다. 주머니는 가볍고, 이 땅에서 당신을 아는 사람은 아무도 없다.

부두 끝 모험가 길드 사레타 지부 앞에 큼직한 공고문이 붙어 있다. "붉은 늑대 용병단 견습 모집. 숙식 제공. 겁쟁이 사절." 공고문 옆에서는 붉은 망토를 두른 여자 용병들이 지원자들을 훑어보며 낄낄거리고 있다.`,
