    text: `그림우드의 검은 숲을 등진 변경 성채 도시 레븐홀트. 성문 앞 장터 뒤편 대장간 거리는 밤낮없이 망치 소리가 그치지 않는 곳이었다. 개척민의 쟁기도, 모험가의 칼도, 변경 기사단의 갑옷도 모두 그 화로들에서 나왔다.

그런데 어젯밤 자정, 거리의 화로들이 한꺼번에 꺼졌다. 커다란 풀무가 숨을 들이켜는 듯한 소리를 들었다는 사람도 있다. 아침이 되자 대장장이들은 새 숯을 쏟아붓고 부싯돌을 쳐 댔지만, 불은 한숨처럼 붙었다가 이내 사그라들었다. 길드에 장비를 맡겨 둔 당신은 언제 찾을 수 있을지 모른다는 말만 들었다.

모험가 길드 레븐홀트 지부의 게시판 앞에서 지부장 브리아가 의뢰서 한 장을 툭 내민다. "숯 수레 하나를 대장간 거리 끝 그리마 철망치네까지 날라 주게. 그 고집 센 드워프 할멈이 숯 탓이라고 우기거든. 보수는 싸지만… 오늘 이 도시에서 일거리가 있는 데는 거기뿐일세."`,
