    text: `그림우드의 검은 숲과 맞닿은 변경 성채 도시 레븐홀트. 숲 가장자리에서 베어 낸 통나무가 북문 초소를 지나 성문 앞 장터로 굴러 들어오는 소리가 이 도시의 아침이었지만, 사흘 전부터 그 소리가 뚝 끊겼다.

북문 밖 벌목장에서 아무도 돌아오지 않은 것이다. 장터에서는 엘프들이 도끼질에 성이 났다느니 숲이 사람을 삼켰다느니 하는 말이 돌고, 변경백 성채 앞마당에서는 병사들이 창을 닦으며 출정 이야기를 주고받는다.

당신이 모험가 길드 레븐홀트 지부의 문을 밀고 들어서자, 의뢰 게시판 앞의 덩치 큰 여자가 돌아본다. 팔뚝에 흉터가 가득한 지부장이 새 의뢰서를 게시판에 탕 박으며 말한다. "마침 잘 왔네. 벌목장에 다녀올 사람이 필요해. 산 사람이 있으면 데려오고, 없으면… 가족한테 돌려줄 몸이라도 데려와. 보수는 내가 넉넉히 쳐 주지."`,
