    text: `왕궁과 태양 대신전, 일곱 층의 백색 탑 마탑 본탑이 서로를 마주 보는 왕도 아스테라. 사흘 전 밤, 저녁 종이 울린 뒤 잠자리에 든 왕이 아침이 되어도 눈을 뜨지 않았다. 숨은 고르고 얼굴은 평온한데, 어떤 치유사도 어떤 기도도 왕을 깨우지 못했다.

왕도는 겉으로는 조용하다. 하지만 대시장 상인들은 곡물값을 올리고, 귀족가 주거지의 마차들은 밤늦도록 오간다. 이레 뒤 섭정을 정할 회의가 열린다는 소문이 돌고, 누가 그 자리에 앉을지를 두고 은잔 여관의 기사들까지 내기를 건다. 모험가 길드 본부에 머물던 당신은 태양 대신전의 치유 행렬을 왕궁까지 호위하는 의뢰를 받았다.

대신전 앞 계단에 흰 옷의 사제들이 성유물 상자를 받쳐 들고 줄지어 선다. 행렬 맨 앞에서 은빛 머리의 대신관이 당신에게 다가와 부드럽게 손을 잡는다. "신께서 우리 임금님을 잠시 쉬게 하셨을 뿐이랍니다. 가는 길에 무슨 일이 있어도, 성유물 상자만은 지켜 주시겠지요?"`,
