    startItems: [{ name: '금저울 상회 후원 증표', kind: 'item', grade: 0, desc: '후원 상회가 금급 심사 후보에게 나눠 준 놋쇠 증표. 금빛 저울이 새겨져 있고, 상회 창고에서 보급품을 받을 수 있다.' }],
