    text: `남해 무역항 사레타. 낮에는 향신료 시장의 호객 소리와 7번 부두의 하역 노래가 끊이지 않지만, 해가 지면 사람들은 하나같이 바다 끝을 돌아본다. 서른 해 전에 불이 꺼지고 반쯤 물에 잠긴 가라앉은 등대가 거기 서 있다.

보름 전부터 그 죽은 등대 꼭대기에 밤마다 붉은 불이 켜진다. 불빛을 항구 등불로 알고 키를 돌린 배들은 등대 아래 암초에 부딪혀 부서졌고, 벌써 일곱 척째다. 총독 관저는 난파선 짐을 주워 가는 검은 돛 해적들이 거짓 불을 피운다며 현상금을 내걸었다.

어젯밤에도 붉은 불이 켜졌다. 갈매기 둥지 여관 창가에서 그 불을 지켜본 당신이 새벽 7번 부두로 나가자, 부서진 판자와 함께 생존자들이 밀려와 있다. 약상자를 멘 여인이 젖은 아이를 담요로 감싸다 당신을 올려다본다. "거기, 힘 좀 쓰겠어요? 이 사람들을 파도의 성소까지 옮겨야 해요."`,
