    text: `해 질 녘, 당신은 순례자 무리 끝에 서서 왕도 아스테라의 남문을 지난다. 언덕 위 왕궁과 일곱 층 백색 탑 사이에서 태양 대신전의 금빛 지붕이 저녁 해를 받고, 그 회랑 창마다 건국 때부터 꺼진 적 없다는 일곱 등불이 비친다. 그런데 그 창 하나가 어둡다.

문지기는 짐을 뒤지며 서두르라고 소리친다. 이틀 전 저녁 첫 등불이 꺼진 뒤로 오래전 폐지된 통금령이 되살아나, 저녁 종이 그친 뒤 거리에 있는 자는 근위대에 끌려간다. 덧문을 내리는 장사꾼들 사이로, 오늘 밤엔 또 어떤 칙령이 돌아오느냐는 수군거림이 오간다.

종탑에서 첫 종이 울리자 순례자들이 겁에 질려 웅성인다. 흰 망토의 젊은 성기사 하나가 인파를 헤치고 와 당신 앞에서 숨을 고른다. 허리의 검보다 손에 든 등잔을 더 소중히 쥔 그녀가 말한다. "신전 경내까지만 가면 통금이 닿지 않아요. 저 혼자서는 이분들을 다 못 모셔요. 마지막 종이 그치기 전에, 같이 가 주시겠어요?"`,
