    text: `남해의 무역항 사레타. 밤에도 짐을 내리는 7번 부두의 등불 너머로 금화와 밀수품, 해적 소문이 한데 섞인다. 당신은 며칠째 선원과 상인들 틈에 섞여 갈매기 둥지 여관 이층 방에 묵고 있다. 아침마다 말수 적은 늙은 여주인이 소금 친 생선과 묽은 맥주를 내오고, 왼눈썹을 가른 오래된 흉터 아래로 손님 하나하나를 조용히 살핀다.

오늘 아침 창밖 7번 부두에 바다 건너 이웃 나라의 깃발을 단 상선이 닿았다. 짐보다 먼저 회색 외투를 걸친 사내들이 내리고, 그들은 영장 같은 종이를 흔들며 부두 일꾼들에게 무언가를 묻는다. 식당의 선원들이 '현상금 사냥꾼'이라고 수군거리고, 두 나라 사이에 휴전이 맺힌 지 열여덟 해가 지났다는 말이 오간다.

주인 한나가 창가에서 한참 부두를 내려다보다 당신 탁자로 와 동화 한 줌과 꼬깃한 쪽지를 내려놓는다. 평소처럼 낮은 목소리지만 앞치마 끈을 쥔 손이 하얗다. "부탁 하나 하지. 향신료 시장에 가서 소금이랑 말린 생선 좀 받아다 줘. 오늘은 내가 문밖에 안 나가는 게 좋겠어."`,
