    text: `그림우드의 검은 숲과 맞닿은 변경 성채 도시 레븐홀트. 해 질 녘 성문을 지나 들어온 당신은 부러진 방패 여관 이층 끝방에 짐을 풀었다. 창밖의 숲은 바람 한 점 없는데도 나무 끝이 모두 북동쪽으로 휘어 있었고, 아래층 손님들은 그 이야기만 나오면 목소리를 낮췄다.

자정 무렵, 복도에서 맨발이 마룻바닥을 밟는 소리에 잠이 깬다. 문틈으로 내다보니 옆방의 젊은 땔감꾼이 눈을 반쯤 뜬 채 계단을 내려가고 있다. 어깨와 머리칼에 잿빛 가루가 묻어 있고, 입술은 누군가에게 길을 묻듯 쉼 없이 달싹인다. 맞은편 방의 투숙객이 그 모습을 보더니 고개를 저으며 문을 걸어 잠근다.

계단 아래에서 등잔을 든 여관 주인이 땔감꾼이 지나가도록 몸을 비켜 선다. 회색 머리를 짧게 친 어깨 넓은 노파가 당신을 올려다보며 낮게 말한다. "깨우지 마시오. 억지로 깨우면 한나절은 제 이름도 못 대니까. 손님, 신발 신고 저 녀석 뒤를 좀 따라가 주겠소? 늘 북문 앞에서 멈추는데, 오늘은 어째 걸음이 빠르오."`,
