    text: `촉 땅의 중심 성도. 차마고도로 떠나는 마방들의 방울 소리가 성문을 메우고, 약초 저잣거리에는 아미산과 청성산에서 내려온 귀한 약재가 산처럼 쌓인다. 당가보와 이름난 문파들이 가까워 칼을 찬 무림인도 흔하지만, 이곳 백성들의 하루는 대개 장터의 흥정 소리로 시작해 다관의 찻물 소리로 끝난다.

당신이 성도에 들어선 날, 약초 저잣거리 한복판에서 비명이 터졌다. 약재를 고르던 젊은 여인 하나가 피를 토하며 쓰러진 것이다. 그녀의 손목에는 낯선 푸른 반점이 번져 있었다. 구경꾼들은 역병이라며 뒤로 물러섰고, 누군가 의원을 부르러 달려갔다.

의원이 오기도 전에 여인의 숨은 가늘어졌고, 저잣거리 상인들은 서둘러 좌판을 덮기 시작했다. 바람결에 "벌써 셋째"라는 수군거림이 섞여 들려온다.`,
