    text: `강남 제일의 부 항주. 대운하를 따라 비단 상단의 배가 끝없이 오가고, 서호의 물안개 너머로 화방의 노랫소리가 흘러나온다. 돈이 모이는 곳에는 사람이 모이고, 사람이 모이는 곳에는 언제나 이름을 날리고 싶은 젊은 무인들이 있다.

오늘 아침 항주 성안 곳곳에 붉은 방이 나붙었다. "후기지수 비무대회 용봉비무, 열흘 뒤 개최. 천하의 젊은 영재를 기다린다." 강남 무림의 이름난 세가와 문파가 후원하는 큰 대회라, 벌써부터 객잔마다 칼과 검을 찬 젊은이들로 북적인다.

청하루 이층 창가에서 당신은 방 앞에 몰려든 사람들을 내려다본다. 참가 명단에 이름을 올리려는 자, 이름난 후기지수의 호위를 구한다는 전단을 돌리는 자, 누가 이길지 내기를 거는 자들이 뒤엉켜 있다.`,
