    text: `게이트 행정의 중심 신해시 중앙구. 유리벽 빌딩 사이로 대형 길드 본사와 각성자관리국 지부가 늘어서 있고, 거리 전광판에서는 오늘의 게이트 공략 소식과 마정석 시세가 쉴 새 없이 흘러간다. 이곳에서 헌터는 직업이고, 게이트는 일상이다.

당신은 이번 주 관리국의 '공략 완료 게이트 사후 점검' 단기 아르바이트를 맡았다. 공략팀이 빠져나간 게이트에 들어가 남은 잔해를 기록하고, 측정기 수치를 확인한 뒤 보고서에 서명만 하면 되는 간단한 일이다. 등급을 가리지 않고 각성자라면 누구나 맡을 수 있는, 몇 안 되는 안전한 돈벌이다.

중앙공원 상설 게이트 앞, 공략이 끝났다는 D급 게이트는 아직 희미하게 일렁이고 있다. 측정기를 켜는 순간, 바늘이 '0'에 머물러야 할 눈금 위로 미세하게 떨린다. 그리고 당신의 피부에도, 분명한 마력의 감촉이 스친다.`,
