    text: `게이트 행정의 중심 신해시 중앙구. 유리벽 빌딩 사이로 대형 길드 본사와 각성자관리국 지부가 늘어서 있고, 거리 전광판에서는 오늘의 게이트 공략 소식과 마정석 시세가 쉴 새 없이 흘러간다. 각성 등급은 한 번 정해지면 평생 따라다니는 낙인이라, 하위 등급 헌터들은 그 숫자 하나에 밥줄이 걸려 있다.

그런데 요즘 하위 등급 헌터들 사이에 믿기 어려운 소식이 돈다. 몇 년째 E급이던 사람이 재측정에서 갑자기 B급이 나왔다는 것이다. 처음엔 측정 오류라고들 했지만, 비슷한 이야기가 하나둘 더 들려온다.

오늘 저녁 강변 먹자골목, 당신은 오랜만에 예전 공략 동료와 마주쳤다. 몇 년째 E급에 묶여 바닥 등급 의뢰만 전전하던 그녀가 새 장비를 걸치고 환하게 웃으며 말한다. "나 B급 됐어. 너도 방법 알고 싶지 않아?"`,
